-- 0072 (M3-H game hardening) — PREFLIGHT. READ ONLY: one SELECT, changes nothing.
-- Run once on the target (staging first; live only after its own approval), immediately before 0072.
-- Part 1: every row must be ok = true, or 0072 is not applied. Part 2: information only.
-- On staging this runs as the read-only action "m3_0072_preflight" of the Staging database workflow.
-- Expected function versions: hashes of the bodies (trailing spaces and Windows line endings ignored).
with checks(part, item, ok, detail) as (
  select 1, '0067 present: match_detail, matches.court_lost_at, closed reason no_court', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_detail') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'matches' and column_name = 'court_lost_at') and (select pg_get_constraintdef(oid) from pg_constraint where conname = 'matches_closed_reason_check') like '%no_court%', ''
  union all select 1, 'release fixes present (0068 blocks policy, 0070 constraint)', exists (select 1 from pg_policies where tablename = 'blocks' and policyname = 'blocks: staff read') and exists (select 1 from pg_constraint where conname = 'clubs_simulated_only_demo'), ''
  union all select 1,'join_match: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '07d5432f9f203da2a0c7c69ebd72451f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), 'missing')
  union all select 1,'leave_match: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'db6bb484d82740641b72d8448f86ebfa' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match'), 'missing')
  union all select 1,'decide_join: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bce21b2e4e717051f838cc1714cc4e96' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), 'missing')
  union all select 1,'set_match_status: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '68feb36c10f79ae33bd6c67db955846f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), 'missing')
  union all select 1,'update_match: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'aa37b42e834acc500cd1f115e2aa4ee3' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), 'missing')
  union all select 1,'post_match: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '548b94f7c81c4805494564c14f213d73' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select 1,'sync_match_with_booking: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '791e9d4948f61fcf788a451ed681420c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking'), 'missing')
  union all select 1,'match_message_notify: the 0001–0071 version 0072 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '485b766738b909d27c67c1435c7d28a6' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), 'missing')
  union all select 1, 'none of 0072''s new objects exists yet (5 functions, chat trigger)', not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname in ('notify_waiting','remove_player','resolve_court','match_message_guard','push_text')) and not exists (select 1 from pg_trigger where tgname = 'match_messages_guard'), ''
  union all select 1, 'no game uses the court-lost state yet (nothing writes it before 0072)', not exists (select 1 from matches where court_lost_at is not null or closed_reason = 'no_court'), ''
  union all select 2, 'organisers already over 10 live games (0072 stops them posting more; nothing else changes)', true, (select count(*)::text from (select organizer_id from matches where status <> 'cancelled' and start_at > now() group by 1 having count(*) >= 10) x)
  union all select 2, 'players already at 20 or more waiting requests (0072 stops further requests)', true, (select count(*)::text from (select mp.profile_id from match_players mp join matches m on m.id = mp.match_id where mp.status = 'pending' and m.status <> 'cancelled' and m.start_at > now() group by 1 having count(*) >= 20) x)
  union all select 2, 'games linked to a confirmed booking (from now on, a cancellation pauses them)', true, (select count(*)::text from matches m join bookings b on b.id = m.booking_id where m.status <> 'cancelled' and b.status = 'confirmed')
)
select part, item, ok, detail from checks order by part, item;
